// Data access for the core tables. Every function takes tenantId: never query without it.
// Agents: add NEW functions in your own module's repo file (calling getDb()); do not edit this file.
import { getDb } from "./db";
import { newId, nowIso } from "./ids";
import { decryptJson, encryptJson } from "./crypto";
import {
  type AgentSettings, type Addon, type AddonKey, type Chunk, type Channel, type ChannelAccount,
  type ContextSection, type ContextSectionKey, type Conversation, type ConversationStatus,
  type Message, type Sender, type Source, type SourceKind, type SourceStatus, CONTEXT_SECTION_KEYS,
} from "./types";

type Row = Record<string, unknown>;
const j = (s: unknown): Record<string, unknown> => { try { return JSON.parse(String(s ?? "{}")); } catch { return {}; } };

// ---------- agent settings ----------
function mapSettings(r: Row): AgentSettings {
  return {
    tenantId: r.tenant_id as string, agentName: r.agent_name as string,
    toneLevel: r.tone_level as AgentSettings["toneLevel"],
    languageDefault: r.language_default as AgentSettings["languageDefault"],
    languageAlt: r.language_alt as AgentSettings["languageAlt"],
    greeting: r.greeting as string, fallbackMessage: r.fallback_message as string,
    handoffEmail: r.handoff_email as string, businessHours: r.business_hours as string,
    crossSellLevel: r.cross_sell_level as AgentSettings["crossSellLevel"], botEnabled: !!r.bot_enabled,
  };
}
export function getAgentSettings(tenantId: string): AgentSettings {
  const db = getDb();
  db.prepare("INSERT OR IGNORE INTO agent_settings (tenant_id) VALUES (?)").run(tenantId);
  return mapSettings(db.prepare("SELECT * FROM agent_settings WHERE tenant_id = ?").get(tenantId) as Row);
}
export function saveAgentSettings(tenantId: string, patch: Partial<Omit<AgentSettings, "tenantId">>): AgentSettings {
  const cur = getAgentSettings(tenantId);
  const n = { ...cur, ...patch };
  const tone = Math.min(5, Math.max(1, Math.round(Number(n.toneLevel)))) as AgentSettings["toneLevel"];
  const cs = Math.min(3, Math.max(0, Math.round(Number(n.crossSellLevel)))) as AgentSettings["crossSellLevel"];
  getDb().prepare(
    `UPDATE agent_settings SET agent_name=?, tone_level=?, language_default=?, language_alt=?, greeting=?,
     fallback_message=?, handoff_email=?, business_hours=?, cross_sell_level=?, bot_enabled=?, updated_at=? WHERE tenant_id=?`
  ).run(n.agentName, tone, n.languageDefault, n.languageAlt, n.greeting, n.fallbackMessage, n.handoffEmail,
    n.businessHours, cs, n.botEnabled ? 1 : 0, nowIso(), tenantId);
  return getAgentSettings(tenantId);
}

// ---------- context sections ----------
export function getContextSections(tenantId: string): ContextSection[] {
  const rows = getDb().prepare("SELECT key, content, updated_at FROM context_sections WHERE tenant_id = ?").all(tenantId) as Row[];
  const by = new Map(rows.map((r) => [r.key as string, r]));
  return CONTEXT_SECTION_KEYS.map((key) => ({
    key, content: (by.get(key)?.content as string) ?? "", updatedAt: (by.get(key)?.updated_at as string) ?? "",
  }));
}
export function saveContextSection(tenantId: string, key: ContextSectionKey, content: string): void {
  if (!CONTEXT_SECTION_KEYS.includes(key)) throw new Error("invalid section");
  getDb().prepare(
    `INSERT INTO context_sections (id, tenant_id, key, content, updated_at) VALUES (?,?,?,?,?)
     ON CONFLICT(tenant_id, key) DO UPDATE SET content=excluded.content, updated_at=excluded.updated_at`
  ).run(newId(), tenantId, key, content, nowIso());
}

// ---------- sources & chunks ----------
const mapSource = (r: Row): Source => ({
  id: r.id as string, tenantId: r.tenant_id as string, kind: r.kind as SourceKind, title: r.title as string,
  url: (r.url as string) ?? null, filePath: (r.file_path as string) ?? null, status: r.status as SourceStatus,
  error: (r.error as string) ?? null, lastSyncedAt: (r.last_synced_at as string) ?? null, createdAt: r.created_at as string,
});
export function listSources(tenantId: string): Source[] {
  return (getDb().prepare("SELECT * FROM sources WHERE tenant_id = ? ORDER BY created_at DESC").all(tenantId) as Row[]).map(mapSource);
}
export function getSource(tenantId: string, id: string): Source | null {
  const r = getDb().prepare("SELECT * FROM sources WHERE tenant_id = ? AND id = ?").get(tenantId, id) as Row | undefined;
  return r ? mapSource(r) : null;
}
export function createSource(tenantId: string, s: { kind: SourceKind; title: string; url?: string; filePath?: string }): Source {
  const id = newId();
  getDb().prepare("INSERT INTO sources (id, tenant_id, kind, title, url, file_path) VALUES (?,?,?,?,?,?)")
    .run(id, tenantId, s.kind, s.title, s.url ?? null, s.filePath ?? null);
  return getSource(tenantId, id)!;
}
export function updateSourceStatus(tenantId: string, id: string, status: SourceStatus, error?: string, contentText?: string): void {
  getDb().prepare(
    "UPDATE sources SET status=?, error=?, content_text=COALESCE(?, content_text), last_synced_at=? WHERE tenant_id=? AND id=?"
  ).run(status, error ?? null, contentText ?? null, nowIso(), tenantId, id);
}
export function deleteSource(tenantId: string, id: string): void {
  const db = getDb();
  db.prepare("DELETE FROM chunks WHERE tenant_id = ? AND source_id = ?").run(tenantId, id);
  db.prepare("DELETE FROM sources WHERE tenant_id = ? AND id = ?").run(tenantId, id);
}
/** Replace all chunks of a source (sourceId) or of a context section (sectionKey). */
export function replaceChunks(tenantId: string, owner: { sourceId?: string; sectionKey?: string }, chunks: { title?: string; text: string }[]): void {
  const db = getDb();
  if (owner.sourceId) db.prepare("DELETE FROM chunks WHERE tenant_id=? AND source_id=?").run(tenantId, owner.sourceId);
  if (owner.sectionKey) db.prepare("DELETE FROM chunks WHERE tenant_id=? AND section_key=?").run(tenantId, owner.sectionKey);
  const ins = db.prepare("INSERT INTO chunks (id, tenant_id, source_id, section_key, title, text) VALUES (?,?,?,?,?,?)");
  for (const c of chunks) ins.run(newId(), tenantId, owner.sourceId ?? null, owner.sectionKey ?? null, c.title ?? "", c.text);
}
export function listChunks(tenantId: string): Chunk[] {
  return (getDb().prepare("SELECT * FROM chunks WHERE tenant_id = ?").all(tenantId) as Row[]).map((r) => ({
    id: r.id as string, tenantId: r.tenant_id as string, sourceId: (r.source_id as string) ?? null,
    sectionKey: (r.section_key as string) ?? null, title: r.title as string, text: r.text as string,
  }));
}

// ---------- conversations & messages ----------
const mapConv = (r: Row): Conversation => ({
  id: r.id as string, tenantId: r.tenant_id as string, channel: r.channel as Channel, externalId: r.external_id as string,
  customerName: r.customer_name as string, status: r.status as ConversationStatus,
  escalationReason: (r.escalation_reason as string) ?? null, state: j(r.state),
  lastMessageAt: r.last_message_at as string, unread: r.unread as number, createdAt: r.created_at as string,
});
const mapMsg = (r: Row): Message => ({
  id: r.id as string, conversationId: r.conversation_id as string, tenantId: r.tenant_id as string,
  direction: r.direction as "in" | "out", sender: r.sender as Sender, body: r.body as string,
  meta: j(r.meta), createdAt: r.created_at as string,
});
export function getOrCreateConversation(tenantId: string, channel: Channel, externalId: string, customerName = ""): Conversation {
  const db = getDb();
  const r = db.prepare("SELECT * FROM conversations WHERE tenant_id=? AND channel=? AND external_id=?").get(tenantId, channel, externalId) as Row | undefined;
  if (r) {
    if (customerName && !r.customer_name) db.prepare("UPDATE conversations SET customer_name=? WHERE id=?").run(customerName, r.id as string);
    return mapConv(db.prepare("SELECT * FROM conversations WHERE id=?").get(r.id as string) as Row);
  }
  const id = newId();
  db.prepare("INSERT INTO conversations (id, tenant_id, channel, external_id, customer_name) VALUES (?,?,?,?,?)")
    .run(id, tenantId, channel, externalId, customerName);
  return mapConv(db.prepare("SELECT * FROM conversations WHERE id=?").get(id) as Row);
}
export function getConversation(tenantId: string, id: string): Conversation | null {
  const r = getDb().prepare("SELECT * FROM conversations WHERE tenant_id=? AND id=?").get(tenantId, id) as Row | undefined;
  return r ? mapConv(r) : null;
}
export function listConversations(tenantId: string, f: { channel?: Channel; status?: ConversationStatus; search?: string; limit?: number } = {}): Conversation[] {
  const where = ["tenant_id = ?"]; const args: (string | number)[] = [tenantId];
  if (f.channel) { where.push("channel = ?"); args.push(f.channel); }
  if (f.status) { where.push("status = ?"); args.push(f.status); }
  if (f.search) { where.push("(customer_name LIKE ? OR external_id LIKE ?)"); args.push(`%${f.search}%`, `%${f.search}%`); }
  args.push(f.limit ?? 200);
  return (getDb().prepare(`SELECT * FROM conversations WHERE ${where.join(" AND ")} ORDER BY last_message_at DESC LIMIT ?`).all(...args) as Row[]).map(mapConv);
}
export function setConversationStatus(tenantId: string, id: string, status: ConversationStatus, reason?: string | null): void {
  getDb().prepare("UPDATE conversations SET status=?, escalation_reason=COALESCE(?, escalation_reason) WHERE tenant_id=? AND id=?")
    .run(status, reason ?? null, tenantId, id);
}
export function setConversationState(tenantId: string, id: string, state: Record<string, unknown>): void {
  getDb().prepare("UPDATE conversations SET state=? WHERE tenant_id=? AND id=?").run(JSON.stringify(state), tenantId, id);
}
export function markConversationRead(tenantId: string, id: string): void {
  getDb().prepare("UPDATE conversations SET unread=0 WHERE tenant_id=? AND id=?").run(tenantId, id);
}
export function addMessage(tenantId: string, conversationId: string, m: { direction: "in" | "out"; sender: Sender; body: string; meta?: Record<string, unknown> }): Message {
  const db = getDb(); const id = newId(); const at = nowIso();
  db.prepare("INSERT INTO messages (id, conversation_id, tenant_id, direction, sender, body, meta, created_at) VALUES (?,?,?,?,?,?,?,?)")
    .run(id, conversationId, tenantId, m.direction, m.sender, m.body, JSON.stringify(m.meta ?? {}), at);
  db.prepare("UPDATE conversations SET last_message_at=?, unread = unread + ? WHERE tenant_id=? AND id=?")
    .run(at, m.direction === "in" ? 1 : 0, tenantId, conversationId);
  return mapMsg(db.prepare("SELECT * FROM messages WHERE id=?").get(id) as Row);
}
export function listMessages(tenantId: string, conversationId: string, limit = 500): Message[] {
  return (getDb().prepare("SELECT * FROM messages WHERE tenant_id=? AND conversation_id=? ORDER BY created_at ASC LIMIT ?")
    .all(tenantId, conversationId, limit) as Row[]).map(mapMsg);
}
/** Real customers only: simulator test conversations are excluded. */
export function countConversationsByStatus(tenantId: string): Record<ConversationStatus, number> {
  const out: Record<ConversationStatus, number> = { bot: 0, needs_human: 0, human: 0, resolved: 0 };
  for (const r of getDb().prepare("SELECT status, COUNT(*) c FROM conversations WHERE tenant_id=? AND channel <> 'simulator' GROUP BY status").all(tenantId) as Row[])
    out[r.status as ConversationStatus] = r.c as number;
  return out;
}

// ---------- add-ons & channel accounts (secrets encrypted) ----------
export function getAddon(tenantId: string, key: AddonKey): Addon {
  const r = getDb().prepare("SELECT * FROM addons WHERE tenant_id=? AND key=?").get(tenantId, key) as Row | undefined;
  return { key, status: (r?.status as Addon["status"]) ?? "disconnected", publicInfo: j(r?.public_info), connectedAt: (r?.connected_at as string) ?? null };
}
export function getAddonSecrets<T = Record<string, unknown>>(tenantId: string, key: AddonKey): T | null {
  const r = getDb().prepare("SELECT config_enc FROM addons WHERE tenant_id=? AND key=?").get(tenantId, key) as Row | undefined;
  return r?.config_enc ? decryptJson<T>(r.config_enc as string) : null;
}
export function saveAddon(tenantId: string, key: AddonKey, v: { status: Addon["status"]; secrets?: unknown; publicInfo?: Record<string, unknown> }): void {
  getDb().prepare(
    `INSERT INTO addons (tenant_id, key, status, config_enc, public_info, connected_at) VALUES (?,?,?,?,?,?)
     ON CONFLICT(tenant_id, key) DO UPDATE SET status=excluded.status,
       config_enc = CASE WHEN excluded.config_enc IS NULL AND excluded.status='disconnected' THEN NULL ELSE COALESCE(excluded.config_enc, addons.config_enc) END,
       public_info=excluded.public_info, connected_at=excluded.connected_at`
  ).run(tenantId, key, v.status, v.secrets ? encryptJson(v.secrets) : null, JSON.stringify(v.publicInfo ?? {}), v.status === "connected" ? nowIso() : null);
}
export function getChannelAccount(tenantId: string, channel: ChannelAccount["channel"]): ChannelAccount {
  const r = getDb().prepare("SELECT * FROM channel_accounts WHERE tenant_id=? AND channel=?").get(tenantId, channel) as Row | undefined;
  return { channel, status: (r?.status as ChannelAccount["status"]) ?? "disconnected", publicInfo: j(r?.public_info) };
}
export function getChannelSecrets<T = Record<string, unknown>>(tenantId: string, channel: ChannelAccount["channel"]): T | null {
  const r = getDb().prepare("SELECT config_enc FROM channel_accounts WHERE tenant_id=? AND channel=?").get(tenantId, channel) as Row | undefined;
  return r?.config_enc ? decryptJson<T>(r.config_enc as string) : null;
}
export function saveChannelAccount(tenantId: string, channel: ChannelAccount["channel"], v: { status: ChannelAccount["status"]; secrets?: unknown; publicInfo?: Record<string, unknown> }): void {
  getDb().prepare(
    `INSERT INTO channel_accounts (tenant_id, channel, status, config_enc, public_info) VALUES (?,?,?,?,?)
     ON CONFLICT(tenant_id, channel) DO UPDATE SET status=excluded.status,
       config_enc = COALESCE(excluded.config_enc, channel_accounts.config_enc), public_info=excluded.public_info`
  ).run(tenantId, channel, v.status, v.secrets ? encryptJson(v.secrets) : null, JSON.stringify(v.publicInfo ?? {}));
}
/** Find which tenant owns an inbound Meta identifier (phone_number_id / page id / ig id) stored in public_info.externalId. */
export function findTenantByChannelExternalId(channel: ChannelAccount["channel"], externalId: string): string | null {
  const rows = getDb().prepare("SELECT tenant_id, public_info FROM channel_accounts WHERE channel=? AND status='connected'").all(channel) as Row[];
  return (rows.find((r) => j(r.public_info).externalId === externalId)?.tenant_id as string) ?? null;
}

export function audit(tenantId: string, actor: string, action: string, detail = ""): void {
  getDb().prepare("INSERT INTO audit_log (id, tenant_id, actor, action, detail) VALUES (?,?,?,?,?)").run(newId(), tenantId, actor, action, detail);
}
